    const targetSelect = element('select', scope);
    for (const [value, label] of [['room', '이 방'], ['global', '공통']]) { const option = element('option', targetSelect, label); option.value = value; }
    targetSelect.value = target;
    targetSelect.addEventListener('change', () => { target = targetSelect.value; draft = structuredClone((target === 'global' ? store.global : store.rooms[key] || store.global) || normalizeTheme({})); apply(); message(''); render(); });
    const tabs = element('div', shell); tabs.className = 'tabs';
